customCommands.command:
bash -c ' COMMIT_HASH="{{.SelectedLocalCommit.Hash}}"; if [ "$COMMIT_HASH" != "$(git rev-parse HEAD)" ]; then
  echo "Error: Żeby to zrobić, musisz być NA TYM commicie (stan --JESTEŚ TUTAJ-- trakcie rebase!).";
  exit 1;
fi; git reset --mixed "$COMMIT_HASH~1" && git commit --allow-empty -C "$COMMIT_HASH" '
